namespace Target;
public static class FileStore
{
    public static string Resolve(string root, string relativePath)
    {
        if (Path.IsPathRooted(relativePath))
        {
            throw new ArgumentException("The path must be relative.", nameof(relativePath));
        }

        var fullRoot = Path.GetFullPath(root);
        var fullPath = Path.GetFullPath(Path.Combine(fullRoot, relativePath));
        var relativeToRoot = Path.GetRelativePath(fullRoot, fullPath);

        if (relativeToRoot == ".." ||
            relativeToRoot.StartsWith(".." + Path.DirectorySeparatorChar, StringComparison.Ordinal) ||
            relativeToRoot.StartsWith(".." + Path.AltDirectorySeparatorChar, StringComparison.Ordinal))
        {
            throw new ArgumentException("The path resolves outside the storage root.", nameof(relativePath));
        }

        return fullPath;
    }
}
